diff --git a/repro/control-no-return.js b/repro/control-no-return.js
new file mode 100644
index 0000000..dde007f
--- /dev/null
+++ b/repro/control-no-return.js
@@ -0,0 +1,14 @@
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
